use crate::{finance::*,live,templates,custom,files};
use serde_json::json;
fn meta()->Metadata{Metadata{template:"General Business".into(),business:Some(Business{company_id:"v5".into(),name:"Test".into(),country:"South Africa".into(),currency:"ZAR".into(),period:"2026-11".into(),year_start:1,..Default::default()}),..Default::default()}}
fn record(category:&str)->Record{Record{id:uuid::Uuid::new_v4().to_string(),revision:1,period:"2026-11".into(),party:"Station".into(),category:category.into(),amount:"0".into(),pricing:Pricing{enabled:true,gross:"1000".into(),discount_percent:"10".into(),discount_fixed:"25".into()},..Default::default()}}
#[test]fn discounts_fuel_paid_adjustments_and_invalid_inputs(){
 let mut m=meta();m.records.push(record("Income"));let mut r=record("Fuel");r.vehicle=Vehicle{price_per_litre:"25".into(),litres:"40".into(),start_odometer:"10000".into(),end_odometer:"10500".into(),..Default::default()};m.records.push(r);
 live::sync_records(&mut m).unwrap();assert_eq!(m.records[0].amount,"875");assert_eq!(m.records[1].amount,"875");assert_eq!(balance(&m.records[1],"").unwrap().status,"Settled");assert_eq!(fuel_distance(&m.records[1]).unwrap().unwrap().1,nonnegative("12.5").unwrap());
 let payment=m.records[1].payments[0].clone();m.records[1].pricing.discount_fixed="100".into();live::sync_records(&mut m).unwrap();assert!(m.records[1].payments.contains(&payment));assert_eq!(balance(&m.records[1],"").unwrap().paid,"800");let count=m.records[1].payments.len();live::sync_records(&mut m).unwrap();assert_eq!(m.records[1].payments.len(),count);
 m.records[1].vehicle.end_odometer="9999".into();assert!(live::sync_records(&mut m).is_err());m.records[1].vehicle.end_odometer="10500".into();m.records[1].pricing.discount_percent="101".into();assert!(live::sync_records(&mut m).is_err());
}
#[test]fn country_measurements(){assert_eq!(custom::units("United States",""),("US gallons","miles","mpg (US)"));assert_eq!(custom::units("South Africa","").0,"litres");let mut r=record("Fuel");r.vehicle=Vehicle{litres:"45.4609".into(),start_odometer:"0".into(),end_odometer:"300".into(),units:"UK".into(),..Default::default()};let (_,e)=custom::fuel_stats(&r,"United Kingdom").unwrap();assert!((nonnegative(&e).unwrap()-nonnegative("30").unwrap()).abs()<nonnegative("0.003").unwrap());}
#[test]fn custom_sheet_selection_additions_roundtrip_and_identifiers(){
 let mut m=meta();m.employees.push(Employee{id:"employee".into(),name:"Ada".into(),number:"0001".into(),structure:"Monthly".into(),rate:"10000".into(),standard_hours:"8".into(),overtime_multiplier:"1.5".into(),identifiers:vec![Identifier{name:"PSIRA number".into(),value:"000012345678901234567890".into()}],contributions:vec![Contribution{name:"Provident fund".into(),total_percent:"10".into(),employee_percent:"50".into(),employer_percent:"50".into(),split_pool:true,..Default::default()}],..Default::default()});
 m.settings["custom_template"]=json!({"name":"My template","sheets":{"Income":{"enabled":true,"columns":{"Tax":false,"Tax percent":false}},"Payroll":{"enabled":true},"Payslips":{"enabled":true}}});
 live::sync_records(&mut m).unwrap();let(mut model,_)=templates::create("General Business",m.business.clone()).unwrap();templates::sync(&mut model,&m).unwrap();assert_eq!(model.get_worksheets_properties().len(),3);
 let payroll=custom::index(&model,"Payroll").unwrap();let max=model.get_model().workbook.worksheets[payroll as usize].dimension().max_column;let col=(1..=max).find(|c|model.get_formatted_cell_value(payroll,3,*c).unwrap()=="PSIRA number").unwrap();assert_eq!(model.get_formatted_cell_value(payroll,4,col).unwrap(),"000012345678901234567890");
 m.settings["custom_template"]["sheets"]["Fuel"]=json!({"enabled":true,"columns":{"Tax included":false,"Deductible amount":false}});m.settings["custom_template"]["sheets"]["Savings Tracker"]=json!({"enabled":true});templates::sync(&mut model,&m).unwrap();assert_eq!(model.get_worksheets_properties().len(),5);let s=custom::index(&model,"Savings Tracker").unwrap();model.set_user_input(s,4,1,"Goal").unwrap();model.set_user_input(s,4,2,"1000").unwrap();model.set_user_input(s,4,3,"200").unwrap();templates::sync(&mut model,&m).unwrap();let s=custom::index(&model,"Savings Tracker").unwrap();assert_eq!(model.get_formatted_cell_value(s,4,4).unwrap(),"800");
 for(s,ws)in model.get_worksheets_properties().iter().enumerate(){for c in 1..=40{assert_ne!(model.get_formatted_cell_value(s as u32,3,c).unwrap(),"Record ID", "{}",ws.name);}}
 let dir=tempfile::tempdir().unwrap();for ext in ["xlsx","ods"]{let file=dir.path().join(format!("v5.{ext}"));files::save(file.to_str().unwrap(),&model,&m).unwrap();let(reopened,loaded)=files::load(file.to_str().unwrap()).unwrap();assert_eq!(loaded.employees[0].identifiers[0].value,"000012345678901234567890");assert_eq!(reopened.get_worksheets_properties().len(),5);}
 let mut b=m.business.clone().unwrap();b.period="2026-12".into();let next=live::rollover(&m,b).unwrap();assert_eq!(next.settings["custom_template"],m.settings["custom_template"]);assert_eq!(next.employees[0].identifiers[0].value,m.employees[0].identifiers[0].value);
}
#[test]fn custom_inventory_hidden_inputs_survive_refresh(){let mut m=meta();let(mut model,_)=templates::create("General Business",m.business.clone()).unwrap();model.set_user_input(8,4,1,"Stock").unwrap();model.set_user_input(8,4,2,"10").unwrap();model.set_user_input(8,4,3,"5").unwrap();model.set_user_input(8,4,4,"2").unwrap();model.set_user_input(8,4,6,"20").unwrap();custom::capture_stock(&model,&mut m).unwrap();m.settings["custom_template"]=json!({"sheets":{"Inventory":{"enabled":true,"columns":{"Opening units":false,"Received":false}}}});templates::sync(&mut model,&m).unwrap();templates::sync(&mut model,&m).unwrap();let max=model.get_model().workbook.worksheets[0].dimension().max_column;let c=(1..=max).find(|c|model.get_formatted_cell_value(0,3,*c).unwrap()=="Stock value").unwrap();assert_eq!(model.get_formatted_cell_value(0,4,c).unwrap().replace(',',"" ),"260.00");}


